/// <summary>
/// enable/disable fields
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[FormDataSourceEventHandler(formDataSourceStr(GUPDiscountClaim, METVendorClaimTable), FormDataSourceEventType::Activated)]
public static void METVendorClaimTable_OnActivated(FormDataSource sender, FormDataSourceEventArgs e)
{
    METVendorClaimTable     metVendorClaimTable = sender.cursor();
    sender.allowEdit(!metVendorClaimTable.Claimed);
}
